settings.custom_css:
selector .ak-nowrap .elementor-heading-title { white-space: nowrap; }
selector .ak-plan-left .ak-g { color: #359742; }
/* dorado de 3 tonos (solo color) */
selector .ak-oro-text .elementor-heading-title { background-image: linear-gradient(to bottom right, #359742 0%, #359742 50%, #359742 100%); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
selector .ak-oro-box .elementor-icon { background-image: linear-gradient(to bottom right, #359742 0%, #359742 50%, #359742 100%) !important; }
selector .ak-plan-dl .elementor-button { border-image: linear-gradient(to bottom right, #359742 0%, #359742 50%, #359742 100%) 1 !important; }
@media (max-width: 1024px) { selector .ak-dk { display: none; } }
selector .ak-mb { display: none; }
@media (max-width: 767px) {
  selector .ak-mb { display: inline; }
  selector .ak-dk { display: none; }
  /* 3 datos en columnas iguales y centrados, como el XD móvil */
  selector .ak-stats-row { display: grid !important; grid-template-columns: repeat(3, 1fr); width: 100%; }
  selector .ak-stat { align-items: center !important; text-align: center; padding-left: 6px !important; padding-right: 6px !important; width: auto !important; }
  selector .ak-stat:not(.ak-stat ~ .ak-stat) { padding-left: 0 !important; }
  selector .ak-stat .elementor-widget-icon .elementor-icon-wrapper, selector .ak-stat .elementor-heading-title { text-align: center; }
  selector .ak-nowrap .elementor-heading-title { white-space: normal; }
  selector .ak-plan-dl { align-self: center; }
}
selector .ak-stat { --width: auto; width: auto; flex: 0 0 auto; }
selector .ak-stats-row { --width: 100%; flex-wrap: nowrap; }
selector .ak-plan-left, selector .ak-plan-right { min-width: 0; }
selector .elementor-widget-text-editor p:last-child { margin-bottom: 0; }
@media (min-width: 1367px) { selector .elementor-element-48da84d4 { max-width: 518px; } }

selector { counter-reset: mod; border-top: 1px solid #CCD0D4; }
/* scroll vertical: se ven 4 módulos completos (4 x 155px desktop / 4 x 117px laptop); sin barras */
selector .e-n-accordion { max-height: 760px; overflow-y: auto; overflow-x: hidden;
  scrollbar-width: none; -ms-overflow-style: none; }
selector .e-n-accordion::-webkit-scrollbar { display: none; width: 0; height: 0; }
selector .e-n-accordion-item > .e-con, selector .e-n-accordion-item > [role="region"] { border: 0 !important; background: none !important; --border-width: 0; margin: 0 !important; }
selector .e-n-accordion-item { counter-increment: mod; box-shadow: inset 0 -1px 0 #CCD0D4; padding: 0 !important; margin: 0 !important; }

/* cabecera: columna "Módulo + número" centrada, título y "Ver contenido +" / "Ocultar −" (líneas finas como el XD) */
selector .e-n-accordion-item-title { display: grid !important; grid-template-columns: 100px minmax(0, 1fr) auto; grid-template-rows: 28px 80px; column-gap: 20px; row-gap: 0;
  align-items: start; padding: 30px 0 31px 0 !important; border: 0 !important; background: none !important; cursor: pointer; list-style: none; }
selector .e-n-accordion-item-title::-webkit-details-marker { display: none; }
selector .e-n-accordion-item-title::before { content: "Módulo"; grid-column: 1; grid-row: 1; justify-self: center; margin-bottom: 4px;
  font: 400 16px/24px Inter, sans-serif; letter-spacing: .1em; text-transform: uppercase; color: #359742; }
selector .e-n-accordion-item-title::after { content: counter(mod, decimal-leading-zero); grid-column: 1; grid-row: 2; justify-self: center;
  font: 500 56px/1.38 Montserrat, sans-serif; letter-spacing: -.032em; color: #359742; }
selector .e-n-accordion-item-title-header { grid-column: 2; grid-row: 2; padding-top: 8px; max-width: 611px; }
/* (sin padding-bottom distinto en [open]: el título mide lo mismo abierto y cerrado) */
selector .e-n-accordion-item-title-text { font: 600 24px/28px Montserrat, sans-serif !important; text-transform: none; color: #0E160F !important; }
selector .e-n-accordion-item-title-icon { grid-column: 3; grid-row: 2; padding-top: 20px; display: flex !important; align-items: center; }


selector .e-n-accordion-item-title-icon > span { align-items: center; gap: 12px;
  font: 500 16px/1 Inter, sans-serif; letter-spacing: .1em; text-transform: uppercase; color: #808591; white-space: nowrap; }
selector .e-n-accordion-item-title-icon .e-closed::before { content: "Ver contenido"; }
selector .e-n-accordion-item-title-icon .e-opened::before { content: "Ocultar"; }
selector .e-n-accordion-item-title-icon > span::after { content: ""; width: 12px; height: 12px; flex: 0 0 12px;
  background: linear-gradient(#808591, #808591) center / 12px 1px no-repeat; }
selector .e-n-accordion-item-title-icon .e-closed::after { background: linear-gradient(#808591, #808591) center / 12px 1px no-repeat, linear-gradient(#808591, #808591) center / 1px 12px no-repeat; }
selector .e-n-accordion-item-title-icon i, selector .e-n-accordion-item-title-icon svg { display: none !important; }

/* contenido: alineado con el título, tarjetas como el XD */
selector .ak-mod-body { padding-left: 120px !important; padding-bottom: 19px !important; }
selector .ak-mod-body > .elementor-widget-text-editor { font: 300 20px/32px Inter, sans-serif !important; letter-spacing: .01em; color: rgba(6,6,6,0.75); }
selector .ak-mod-body > .elementor-widget-text-editor p { font: inherit !important; }
selector .ak-mod-body .elementor-heading-title { font: 600 20px/1.4 Montserrat, sans-serif !important; color: #0E160F !important; }
selector .ak-mod-body .e-con .elementor-widget-text-editor, selector .ak-mod-body .e-con .elementor-widget-text-editor p { font: 300 16px/21px Inter, sans-serif !important; letter-spacing: .01em; color: rgba(6,6,6,0.75); }
selector .ak-mod-body > .e-con > .e-con:not(.e-con ~ .e-con) { background-color: #EBEFF2 !important; }
selector .ak-mod-body > .e-con > .e-con:not(:has(~ .e-con)) { background-color: #F0F5F0 !important; }

@media (max-width: 1366px) {
  selector .e-n-accordion { max-height: 600px; }
  selector .e-n-accordion-item-title { grid-template-columns: 72px minmax(0, 1fr) auto; grid-template-rows: 22px 50px; column-gap: 14px; padding: 22px 0 23px !important; }
  selector .e-n-accordion-item-title::before { font-size: 11px; line-height: 18px; }
  selector .e-n-accordion-item-title::after { font-size: 36px; }
  selector .e-n-accordion-item-title-header { padding-top: 6px; max-width: 435px; }
  selector .e-n-accordion-item-title-text { font-size: 17px !important; line-height: 22px !important; }
  selector .e-n-accordion-item-title-icon { padding-top: 8px; }
  selector .e-n-accordion-item-title-icon > span { font-size: 14px; }
  selector .ak-mod-body { padding-left: 86px !important; padding-bottom: 25px !important; }
  selector .ak-mod-body > .elementor-widget-text-editor { font-size: 16px !important; }
  selector .ak-mod-body .elementor-heading-title { font-size: 16px !important; }
  selector .ak-mod-body .e-con .elementor-widget-text-editor, selector .ak-mod-body .e-con .elementor-widget-text-editor p { font-size: 16px !important; line-height: 22px !important; }
}
@media (max-width: 767px) {
  selector .e-n-accordion { max-height: none; overflow: visible; }
  selector .e-n-accordion-item-title { grid-template-columns: 50px minmax(0, 1fr) auto; grid-template-rows: auto auto; column-gap: 12px; padding: 18px 0 19px !important; }
  selector .e-n-accordion-item-title::before { font-size: 10px; line-height: 14px; }
  selector .e-n-accordion-item-title::after { font-size: 36px; }
  selector .e-n-accordion-item-title-header { padding-top: 4px; max-width: none; }
  selector .e-n-accordion-item-title-text { font: 500 15px/20px Montserrat, sans-serif !important; letter-spacing: -.01em; }
  selector .e-n-accordion-item-title-icon { padding-top: 6px; }
  selector .e-n-accordion-item-title-icon > span { font-size: 12px; gap: 8px; }
  selector .ak-mod-body { padding-left: 0 !important; padding-bottom: 21px !important; }
  selector .ak-mod-body > .elementor-widget-text-editor { font-size: 14px !important; line-height: 22px !important; }
  selector .ak-mod-body .elementor-heading-title { font-size: 16px !important; }
  selector .ak-mod-body .e-con .elementor-widget-text-editor, selector .ak-mod-body .e-con .elementor-widget-text-editor p { font-size: 14px !important; line-height: 22px !important; }
}
selector .ak-mod-body > .e-con > .e-con { flex-shrink: 1 !important; min-width: 0; border-radius: 8px; }
selector .e-n-accordion-item[open] > .e-con { animation: ak-mod-in .4s cubic-bezier(.22,.61,.36,1) both; }
@keyframes ak-mod-in { from { opacity: 0; } to { opacity: 1; } }
@media (prefers-reduced-motion: reduce) { selector .e-n-accordion-item[open] > .e-con { animation: none; } }
selector .e-n-accordion-item-title-icon { display: grid !important; justify-items: end; align-items: center; }
selector .e-n-accordion-item-title-icon > span { grid-area: 1 / 1; }

/* desktop como el Figma: párrafo -> tarjetas 20 px; tarjetas de 176 px con el título a 22 px del borde */
@media (min-width: 1367px) {
  selector .ak-mod-body { --gap: 20px 20px; --row-gap: 20px; }
  selector .ak-mod-body > .e-con > .e-con { min-height: 176px; --padding-top: 22px; --gap: 8px 8px; --row-gap: 8px; }
}
/* cierre sin salto y transiciones (ver comentario arriba) */
selector .ak-mod-body > :first-child { margin-top: -29px !important; }
@media (max-width: 1366px) { selector .ak-mod-body > :first-child { margin-top: -21px !important; } }
@media (max-width: 767px) { selector .ak-mod-body > :first-child { margin-top: -17px !important; } }
selector .e-n-accordion-item-title-icon > span { display: inline-flex !important; grid-area: 1 / 1; opacity: 0; visibility: hidden; transition: opacity .45s cubic-bezier(.22,.61,.36,1), visibility .45s cubic-bezier(.22,.61,.36,1), color .45s cubic-bezier(.22,.61,.36,1); }
selector .e-n-accordion-item:not([open]) .e-n-accordion-item-title-icon .e-closed, selector .e-n-accordion-item[open] .e-n-accordion-item-title-icon .e-opened { opacity: 1; visibility: visible; }
@media (prefers-reduced-motion: reduce) { selector .e-n-accordion-item-title-icon > span { transition: none !important; } }

/* fondo igual al de la sección: cubre la franja bajo la sección mientras está fijada */
selector { background-color: #FDFCFB; }
/* Propuesta A: sección de módulos fijada mientras la lista avanza (solo desktop y laptop) */
selector.is-on > .ak-plan { position: sticky !important; }
@media (min-width: 1367px) { selector.is-on > .ak-plan { top: 90px; } }
@media (min-width: 1025px) and (max-width: 1366px) { selector.is-on > .ak-plan { top: 80px; } }
selector.is-on .e-n-accordion { overflow: hidden !important; }
selector .ak-plan-prog { display: none; position: absolute; left: 0; bottom: 0; height: 3px; width: 100%; background: #359742; transform-origin: 0 50%; transform: scaleX(0); pointer-events: none; }
selector.is-on .ak-plan-prog { display: block; }
